// package b 里 import "example.com/myapp/a"
//
// go build 直接报错：
// import cycle not allowed

package main

import (
	"fmt"
	mrand "math/rand"
	"math/rand/v2"
	"strings"
)

// Config 里大写字段导出，小写字段只有本包能用
type Config struct {
	Host string
	port int
}

// 小写开头：包内可见，包外访问不到
func normalize(s string) string {
	return strings.TrimSpace(strings.ToLower(s))
}

func main() {
	// 同包内可以直接用未导出的 normalize
	c := Config{Host: normalize("  LocalHost  "), port: 8080}

	// 分组导入用包名引用，别名导入用别名引用
	fmt.Println(c.Host, c.port)
	fmt.Println(mrand.Intn(100), rand.IntN(100))
}
